'use strict';
// Audit only: inspect the ACTUAL AAC asset shipped in the PWA.
// No browser sound permissions, IndexedDB, or game state involved.
// Requires ffmpeg/ffprobe on the Ubuntu CI runner.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { execFileSync } = require('node:child_process');
const site = process.argv[2] || '_site';
const filename = 'audio/gitailab_rainforest_ios_seamless_loop_48k.m4a';
const file = path.join(site,'exhibit',filename);
const root = path.join(site,filename);
const manifest = JSON.parse(fs.readFileSync(path.join(site,'exhibit/precache.json'),'utf8'));
assert.ok(manifest.includes(filename),'standalone AAC must be precached for offline PWA');
assert.ok(fs.existsSync(file)&&fs.existsSync(root));
assert.deepEqual(fs.readFileSync(file),fs.readFileSync(root),'source and scoped AAC are identical');
function cli(cmd,args,opts={}){
 try{return execFileSync(cmd,args,{maxBuffer:16*1024*1024,...opts});}
 catch(error){throw Error(cmd+' audio inspection failed: '+(error.stderr?.toString()||error.message));}
}
const metadata=JSON.parse(cli('ffprobe',['-v','error','-show_entries',
 'stream=codec_name,codec_type,sample_rate,channels,duration:format=duration,size',
 '-of','json',file]).toString());
const streams=metadata.streams||[];
assert.equal(streams.length,1,'iOS BGM must contain exactly one stream');
assert.equal(streams[0].codec_name,'aac');
assert.equal(streams[0].sample_rate,'48000');
assert.equal(streams[0].channels,1);
const duration=Number(metadata.format.duration);
assert.ok(duration>40&&duration<48,'seamless AAC should last approx. 45 seconds');
assert.ok(Number(metadata.format.size)>100000,'audio must not be empty/placeholder');
// Packet timestamps must move forward across the COMPLETE 45-second file,
// not repeatedly reset at 4 seconds. This is metadata, not audible validation.
const packets=JSON.parse(cli('ffprobe',['-v','error','-select_streams','a:0',
 '-show_packets','-show_entries','packet=pts_time,duration_time','-of','json',file]).toString()).packets;
assert.ok(packets.length>1600,'all AAC frames must be present');
let prev=NaN, largestGap=0, rewind=0, last=-1;
for(const p of packets){
 const pts=Number(p.pts_time);
 if(!Number.isFinite(pts))continue;
 if(Number.isFinite(prev)){
   if(pts<prev-0.0001)rewind++;
   largestGap=Math.max(largestGap,pts-prev);
 }
 prev=pts;last=pts;
}
assert.equal(rewind,0,'AAC packet PTS must never jump backward');
assert.ok(largestGap<0.07,'no missing 4-second timestamp gaps');
assert.ok(last>duration-0.2,'final AAC frames must extend to the declared end');
// Decode the real file in CI, then compare 4-second PCM windows.
// A single baked-in ~4-second clip repeated for 45s would have <=2 unique
// chunks. Natural rainforest recording should yield many different windows.
const pcm=cli('ffmpeg',['-nostdin','-hide_banner','-loglevel','error','-i',file,
 '-map','0:a:0','-vn','-ac','1','-ar','8000','-f','s16le','pipe:1']);
const sampleRate=8000, chunkSamples=4*sampleRate, chunkBytes=chunkSamples*2;
const pcmSeconds=pcm.length/(sampleRate*2);
assert.ok(pcmSeconds>40&&pcmSeconds<48,'the entire AAC must be decodable to PCM');
const hashes=new Set();
let totalPower=0;
for(let offset=0;offset+chunkBytes<=pcm.length;offset+=chunkBytes){
 const window=pcm.subarray(offset,offset+chunkBytes);
 hashes.add(crypto.createHash('sha256').update(window).digest('hex'));
 for(let i=0;i<window.length;i+=2){
   const v=window.readInt16LE(i)/32768;
   totalPower+=v*v;
 }
}
const chunks=Math.floor(pcm.length/chunkBytes);
assert.ok(chunks>=10 && hashes.size>=9,'source audio must NOT be a baked-in 4-second clip repeated');
const rms=Math.sqrt(totalPower/(chunks*chunkSamples));
assert.ok(rms>0.0001 && rms<0.95,'decoded audio level must be nonzero and bounded');
console.log('AAC container audit: '+JSON.stringify({
 codec:streams[0].codec_name,rate:streams[0].sample_rate,
 channels:streams[0].channels,duration_s:+duration.toFixed(3),
 packets:packets.length,pts_rewinds:rewind,max_pts_gap_s:+largestGap.toFixed(4),
 decoded_s:+pcmSeconds.toFixed(3),four_second_chunks:chunks,
 unique_four_second_chunks:hashes.size,rms:+rms.toFixed(5),
 file_bytes:fs.statSync(file).size
}));
console.log('Limitation: ffprobe and PCM prove the file is structurally sound; they cannot prove iOS WebKit playback or prevent a short loop generated by the browser.');
